// Theme registry. The colours themselves live in src/styles/themes.css
// (generated by scripts/generate-themes.js); this file is what the UI uses to
// list, apply and remember them.
export const THEMES = [
  {
    id: "daylight",
    name: "Daylight",
    blurb: "Warm paper, teal & coral",
    swatch: ["#F6F4EC", "#0F766E", "#E5573A"],
  },
  {
    id: "lavender",
    name: "Lavender",
    blurb: "Soft violet & peach",
    swatch: ["#F5F3FC", "#6D4AE6", "#F2784B"],
  },
  {
    id: "midnight",
    name: "Midnight",
    blurb: "Deep navy & emerald",
    swatch: ["#0A101C", "#2DD4A0", "#38BDF8"],
  },
  {
    id: "ember",
    name: "Ember",
    blurb: "Plum & rose gold",
    swatch: ["#130D17", "#F5A25D", "#F472B6"],
  },
]

export const DEFAULT_THEME = "daylight"
const STORAGE_KEY = "learnify-theme"

export function getStoredTheme() {
  try {
    const t = localStorage.getItem(STORAGE_KEY)
    return THEMES.some((x) => x.id === t) ? t : DEFAULT_THEME
  } catch {
    return DEFAULT_THEME
  }
}

export function applyTheme(id) {
  document.documentElement.setAttribute("data-theme", id)
  try {
    localStorage.setItem(STORAGE_KEY, id)
  } catch {
    /* private mode — the theme still applies for this visit */
  }
  window.dispatchEvent(new CustomEvent("learnify-theme", { detail: id }))
}

// Read a theme colour token (e.g. "yellow-50") as a CSS colour, for libraries
// such as Chart.js that can't use Tailwind classes.
export function themeColor(token, alpha = 1) {
  const raw = getComputedStyle(document.documentElement).getPropertyValue(`--${token}`).trim()
  const channels = raw.split(/\s+/).join(", ")
  return alpha < 1 ? `rgba(${channels}, ${alpha})` : `rgb(${channels})`
}

const CHART_TOKENS = ["yellow-50", "richblue-300", "blue-100", "caribbeangreen-100", "brown-100", "pink-200"]
export const chartPalette = (n) =>
  Array.from({ length: n }, (_, i) => themeColor(CHART_TOKENS[i % CHART_TOKENS.length]))
